regCheckBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "regCheckBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "AssumptionsLab",
                name = "regCheck",
                version = c(1,0,0),
                options = options,
                results = regCheckResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'auto')
        }))

#' Simple and Multiple Regression
#'
#' 
#' @param data .
#' @param dep .
#' @param covs .
#' @param factors .
#' @param reportLang .
#' @param showPlots Uncheck for a text-only report.
#' @param linShowPlots .
#' @param linSmoother .
#' @param linShowBand .
#' @param linRefLine .
#' @param normShowPlots .
#' @param normQQBand .
#' @param normHistBins .
#' @param normCurveOverlay .
#' @param normFlagOutliers .
#' @param homoShowPlots .
#' @param homoSmoother .
#' @param homoShowBand .
#' @param corrShowIndividual .
#' @param corrShowComparative .
#' @param corrIndividualFit .
#' @param corrComparativeStyle .
#' @param corrHighlightDiscordant .
#' @param influenceShowPlots .
#' @param influenceLabelMode .
#' @param influenceShowThreshold .
#' @param plotPalette .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$intro} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$designGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$modelSummary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$missingSummary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$linearityGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$linearityPredictor} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$linearityModel} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$linearityInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$correlationMatrixGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$pearsonMatrixTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$dcorMatrixTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$correlationMatrixNote} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$correlationComparisonGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$correlationComparisonTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$correlationComparisonInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$correlationIndividualPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$correlationIndividualGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$correlationComparativePlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$correlationComparativeGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$diagnosticPlotsGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$residualsFittedPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$residualsFittedGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$observedPredictedPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$observedPredictedGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$predictorEffectsPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$predictorEffectsGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$residualNormalityGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$residualNormality} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$residualNormalityInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$qqResidualsPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$qqResidualsGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$residualHistogramPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$residualHistogramGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$residualNormalCurvePlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$residualNormalCurveGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$homoscedasticityGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$homoscedasticity} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$homoscedasticityInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$scaleLocationPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$scaleLocationGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$independenceGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$independence} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$independenceInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$multicollinearityGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$multicollinearity} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$multicollinearityInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$influenceGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$influence} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$influenceInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$numericBoxplotsPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$numericBoxplotsGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$residualsLeveragePlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$residualsLeverageGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$cooksDPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$cooksDGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$transformationsGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$transformationNormality} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$transformationFit} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$robustOptionsGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$robustOptionsText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$modelSummary$asDF}
#'
#' \code{as.data.frame(results$modelSummary)}
#'
#' @export
regCheck <- function(
    data,
    dep,
    covs = NULL,
    factors = NULL,
    reportLang = "en",
    showPlots = TRUE,
    linShowPlots = TRUE,
    linSmoother = "none",
    linShowBand = FALSE,
    linRefLine = TRUE,
    normShowPlots = TRUE,
    normQQBand = TRUE,
    normHistBins = "sturges",
    normCurveOverlay = TRUE,
    normFlagOutliers = TRUE,
    homoShowPlots = TRUE,
    homoSmoother = "none",
    homoShowBand = FALSE,
    corrShowIndividual = TRUE,
    corrShowComparative = TRUE,
    corrIndividualFit = TRUE,
    corrComparativeStyle = "dumbbell",
    corrHighlightDiscordant = TRUE,
    influenceShowPlots = TRUE,
    influenceLabelMode = "top5",
    influenceShowThreshold = TRUE,
    plotPalette = "jamovi") {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("regCheck requires jmvcore to be installed (restart may be required)")

    if ( ! missing(dep)) dep <- jmvcore::resolveQuo(jmvcore::enquo(dep))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if ( ! missing(factors)) factors <- jmvcore::resolveQuo(jmvcore::enquo(factors))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(dep), dep, NULL),
            `if`( ! missing(covs), covs, NULL),
            `if`( ! missing(factors), factors, NULL))

    for (v in factors) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- regCheckOptions$new(
        dep = dep,
        covs = covs,
        factors = factors,
        reportLang = reportLang,
        showPlots = showPlots,
        linShowPlots = linShowPlots,
        linSmoother = linSmoother,
        linShowBand = linShowBand,
        linRefLine = linRefLine,
        normShowPlots = normShowPlots,
        normQQBand = normQQBand,
        normHistBins = normHistBins,
        normCurveOverlay = normCurveOverlay,
        normFlagOutliers = normFlagOutliers,
        homoShowPlots = homoShowPlots,
        homoSmoother = homoSmoother,
        homoShowBand = homoShowBand,
        corrShowIndividual = corrShowIndividual,
        corrShowComparative = corrShowComparative,
        corrIndividualFit = corrIndividualFit,
        corrComparativeStyle = corrComparativeStyle,
        corrHighlightDiscordant = corrHighlightDiscordant,
        influenceShowPlots = influenceShowPlots,
        influenceLabelMode = influenceLabelMode,
        influenceShowThreshold = influenceShowThreshold,
        plotPalette = plotPalette)

    analysis <- regCheckClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

